// Copied from plantafoodforest's server/model/species.ts. The library build script joins it with the Codex
// data cards for zones, yields, harvest months, colours and plant form.
import type { Form, Region, Strata, Succession } from '../shared/types'

export type Role = 'fruit' | 'berry' | 'nut' | 'timber' | 'support' | 'nfix' | 'biomass' | 'flower' | 'staple' | 'wildlife' | 'medicinal' | 'herb'
export interface Variety { name: string; harvest: [number, number] }

// The model's knowledge base. Figures are rough planning numbers (mature yield per plant, years to first
// meaningful harvest, direct-to-customer price) meant to rank and compare designs, not to promise outcomes.
// Harvest months are for the Northern Hemisphere; the engine shifts them for southern sites.
// Strata follow Götsch: assigned by light demand within a consortium, not strictly by height.

export interface Species {
  id: string
  name: string
  latin: string
  emoji: string
  strata: Strata
  succession: Succession
  form: Form
  roles: Role[]
  h: number // mature height, m (managed)
  w: number // canopy width, m
  dec: boolean // deciduous
  leaf: string
  fruit?: string
  ytf: number // years to first harvest (0 = not a harvest crop)
  kg: number // mature yield per plant per year
  harvest?: [number, number]
  life: number // productive lifespan in the system, years
  price?: number // USD per kg
  zMin: number // USDA zone range, .5 = "b"
  zMax: number
  chill?: number // chill hours needed
  natives: Region[]
  dry?: boolean // copes with a long dry season
  invasive?: boolean
  pollard?: boolean
  rare?: boolean // unusual / collector fruit
  varieties?: Variety[]
  uses?: ('culinary' | 'tea' | 'medicinal' | 'pollinator' | 'aromatic')[] // herb layer: spread picks across different uses
  note?: string
}

const sp = (s: Species) => s

type HerbInput = Pick<Species, 'id' | 'name' | 'latin' | 'emoji' | 'zMin' | 'zMax' | 'natives'> & Partial<Species>
const herb = (h: HerbInput): Species => ({
  strata: 'ground', succession: 'secondary', form: 'herb', roles: ['herb', 'medicinal'], uses: ['medicinal'],
  h: 0.5, w: 0.5, dec: false, leaf: '#5aa64a', ytf: 1, kg: 1, harvest: [5, 10], life: 10, price: 18, ...h,
})
// low woody herbs sit in the shrub layer
const shrubHerb = (h: HerbInput): Species => herb({ strata: 'low', form: 'shrub', h: 0.9, w: 0.9, life: 15, ...h })

